-- CODE-LOOP-TERMINAL-RECONCILE-2 (2026-10-19, pillar autonomy; agent_issues 100152, filed by CRON-WATCH-1 as
-- CRON-FAULT-1: task-failed:code-loop-terminal-reconcile, 3 failures in a row, escalated). The */10 fleet task closes an open
-- CODE-LOOP-EXHAUSTED-1 issue once its code task reached merged, by writing issue_triage. Since CLOSE-BINDS-TO-PROBE-1
-- (2026-10-18) the trigger issue_close_evidence_required aborts a close while the issue's contract reads fail, and one such issue
-- aborted the whole statement, so no issue closed: 100090 (its code-read probe failed before PR 2857 merged) and 100089, whose
-- birth probe reads ok only once the issue is closed, so it can never pass and blocked the task every run.
-- Version 2: step retarget-circular-probe points that self-referential birth probe at the merged code task (the exhaustion's
-- real definition of done: SELECT status FROM code_tasks) and makes it due now, so the contract runner re-probes; step
-- close-merged skips an issue whose contract currently fails, so one failing probe no longer stops the others, and it closes
-- after its probe passes. No probe verdict is written here: the runners decide.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE fleet_tasks SET definition = '{"steps":[{"type":"sql","db":"AUDIT","sql":"INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT a.id, ''code-loop-terminal-reconcile'', ''resolved'', ''qnfo-code-orchestrator'', datetime(''now'',''+1 day''), ''DoD met: code task '' || t.id || '' reached merged (PR '' || COALESCE(t.pr_url,''unknown'') || ''); code_tasks.status=merged. Auto-closed by CODE-LOOP-TERMINAL-RECONCILE-1.'' FROM agent_issues a JOIN (SELECT id, substr(substr(title, instr(title,''CODE-LOOP-EXHAUSTED-1: '')+23), 1, instr(substr(title, instr(title,''CODE-LOOP-EXHAUSTED-1: '')+23),'' '')-1) ct FROM agent_issues WHERE title LIKE ''%CODE-LOOP-EXHAUSTED-1: ct_%'') x ON x.id = a.id JOIN code_tasks t ON t.id = x.ct WHERE a.status=''open'' AND instr(substr(a.title, instr(a.title,''CODE-LOOP-EXHAUSTED-1: '')+23),'' '') > 0 AND t.status=''merged'' ON CONFLICT(issue_id) DO UPDATE SET triage_state=''resolved'', close_evidence=excluded.close_evidence"}]}', version = 1 WHERE id = 'code-loop-terminal-reconcile'

UPDATE fleet_tasks SET definition = '{"steps": [{"type": "sql", "name": "retarget-circular-probe", "db": "AUDIT", "sql": "UPDATE remediation_contracts SET verify_probe = ''SELECT ''''merged'''' AS expected, COALESCE((SELECT status FROM code_tasks WHERE id = '''''' || (SELECT t.id FROM agent_issues a JOIN code_tasks t ON instr(a.title, ''CODE-LOOP-EXHAUSTED-1: '' || t.id || '' '') > 0 WHERE a.id = remediation_contracts.issue_id AND a.status = ''open'' AND t.status = ''merged'') || ''''''), ''''missing'''') AS observed'', verify_transport = ''d1-query'', module = ''code-loop-terminal-reconcile'', next_due_at = datetime(''now'') WHERE status IN (''active'',''holding'') AND issue_id IN (SELECT a.id FROM agent_issues a JOIN code_tasks t ON instr(a.title, ''CODE-LOOP-EXHAUSTED-1: '' || t.id || '' '') > 0 WHERE a.status = ''open'' AND t.status = ''merged'') AND instr(verify_probe, ''FROM agent_issues WHERE id = '') > 0 AND instr(verify_probe, '') <> ''''open'''' THEN ''''ok'''''') > 0"}, {"type": "sql", "name": "close-merged", "db": "AUDIT", "sql": "INSERT INTO issue_triage (issue_id, rc, triage_state, owner, sla_due_at, close_evidence) SELECT a.id, ''code-loop-terminal-reconcile'', ''resolved'', ''qnfo-code-orchestrator'', datetime(''now''), ''DoD met: code task '' || t.id || '' reached merged (PR '' || COALESCE(t.pr_url,''unknown'') || ''); code_tasks.status=merged. Auto-closed by CODE-LOOP-TERMINAL-RECONCILE-1.'' FROM agent_issues a JOIN code_tasks t ON instr(a.title, ''CODE-LOOP-EXHAUSTED-1: '' || t.id || '' '') > 0 WHERE a.status = ''open'' AND t.status = ''merged'' AND NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.issue_id = a.id AND c.status IN (''active'',''holding'') AND COALESCE(c.last_verdict,'''') IN (''fail'',''vacuous-probe-result'',''probe-error'',''probe-not-machine-executable'',''probe-same-account-host'')) ON CONFLICT(issue_id) DO UPDATE SET triage_state=''resolved'', close_evidence=excluded.close_evidence"}]}', version = 2, updated_at = datetime('now') WHERE id = 'code-loop-terminal-reconcile';

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('reconcile-close-aborts-batch', 'one issue the close guard refuses aborts a set-based close task, so no issue in the batch closes',
  'an INSERT ... SELECT into issue_triage closes every matching issue in one statement; issue_close_evidence_required raises ABORT for any one whose contract fails',
  'filter the batch on the same contract condition the guard checks, and retarget a probe that can only pass after the close (CODE-LOOP-TERMINAL-RECONCILE-2)',
  'fleet_runs for code-loop-terminal-reconcile is ok', 'fm-reconcile-close-aborts-batch', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), 100152,
  'an open CODE-LOOP-EXHAUSTED-1 issue with a merged task and a failing contract', 'the task fails every 10 minutes with close-while-contract-fails',
  'every CODE-LOOP-EXHAUSTED-1 issue whose task merged stays open');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-reconcile-close-aborts-batch', NULL, 'CODE-LOOP-TERMINAL-RECONCILE-2', 'failure-mode detector',
  'SELECT ''ok'' AS expected, COALESCE((SELECT status FROM fleet_runs WHERE task_id = ''code-loop-terminal-reconcile'' ORDER BY id DESC LIMIT 1), ''none'') AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now'));
